import { PrismaClient } from '../node_modules/.prisma/client/index.js';


//generated by chatGPT

const prisma = new PrismaClient();

async function main() {

  console.log('🧹 Cleaning up old data...');

  await prisma.booking.deleteMany({});
  await prisma.review.deleteMany({});
  await prisma.tourSlot.deleteMany({});
  await prisma.place.deleteMany({});
  await prisma.user.deleteMany({});

  console.log('👥 Seeding 3 users...');
  const user1 = await prisma.user.create({ data: { name: 'Sara' } });
  const user2 = await prisma.user.create({ data: { name: 'Abel' } });
  const user3 = await prisma.user.create({ data: { name: 'Liya' } });

  console.log('🏛️ Seeding places and reviews...');
  
  // 1. National Museum (Lots of reviews, high average)
  const museum = await prisma.place.create({
    data: {
      name: 'National Museum',
      category: 'History',
      description: 'Home of Lucy and ancient human history.',
      openingHours: '08:30–17:30',
    },
  });

  await prisma.review.createMany({
    data: [
      { placeId: museum.id, userId: user1.id, rating: 5, body: 'Go early, the guide is excellent.' },
      { placeId: museum.id, userId: user2.id, rating: 4, body: 'Great, but the café was closed.' },
      { placeId: museum.id, userId: user3.id, rating: 5, body: 'Incredible collection!' },
    ],
  });

  // 2. Brand-new Café (The Bug Placeholder: One 5-star review shouldn't beat the museum)
  const cafe = await prisma.place.create({
    data: {
      name: 'Brand-new Café',
      category: 'Food',
      description: 'Freshly roasted local coffee beans.',
      openingHours: '07:00–22:00',
    },
  });
  await prisma.review.create({
    data: { placeId: cafe.id, userId: user1.id, rating: 5, body: 'Amazing macchiato, first customer!' },
  });

  // 3. Entoto Park
  const park = await prisma.place.create({
    data: {
      name: 'Entoto Park',
      category: 'Nature',
      description: 'Stunning panoramic views and walking trails.',
      openingHours: '06:00–20:00',
    },
  });
  await prisma.review.createMany({
    data: [
      { placeId: park.id, userId: user2.id, rating: 4, body: 'Very peaceful place.' },
      { placeId: park.id, userId: user3.id, rating: 5, body: 'Clean air and great running tracks.' },
    ],
  });

  console.log('🎟️ Seeding Tour Slots...');
  // Create a slot with only 1 seat left to test parallel overbooking later
  await prisma.tourSlot.create({
    data: {
      placeId: museum.id,
      startsAt: new Date('2026-11-07T09:00:00Z'),
      capacity: 10,
      bookings: {
        createMany: {
          data: [
            { userId: user1.id, seats: 4 },
            { userId: user2.id, seats: 5 }, // 9 seats booked total, only 1 left!
          ],
        },
      },
    },
  });

  console.log('✅ Seeding complete!');
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
